contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.addToBalance{value: amount}();

        uint beforeContractBalance = address(c).balance;
        uint beforeUserBalance = c.getBalance(address(this));

        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.getBalance(address(this)) == beforeUserBalance && address(c).balance == beforeContractBalance);
        } else {
            assert(c.getBalance(address(this)) == 0 && address(c).balance == beforeContractBalance - beforeUserBalance);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, address u) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "not enough balance");
        uint beforeCaller = c.getBalance(address(this));
        uint beforeOther = c.getBalance(u);
        c.addToBalance{value: amount}();
        uint afterCaller = c.getBalance(address(this));
        uint afterOther = c.getBalance(u);
        assert(afterCaller == beforeCaller + amount && afterOther == beforeOther);
    }

    receive() external payable {}
}
